INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.414, "2025/01/31 12:00:00", 2, "カリン", 0.0, 1, -416.5, 190801, 1000001, 1, "2030/01/01 14:59:59", 62, 1, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.099, "2025/01/31 12:00:00", 2, "カリン", 0.0, 2, -416.5, 190801, 1000002, 1, "2030/01/01 14:59:59", 62, 1, "ミッションをクリアして、\n報酬をゲットしましょう！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.801, "2025/01/31 12:00:00", 2, "カリン", 0.0, 3, -416.5, 190801, 1000003, 1, "2030/01/01 14:59:59", 63, 1, "受け取ることができる\n報酬があるようです\n確認してみてください");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "2025/01/31 12:00:00", 2, "カリン", 0.0, 4, -416.5, 190801, 1000004, 1, "2030/01/01 14:59:59", 63, 2, "報酬がもらえますよ！\nチェックしてみてください");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.12, "2025/01/31 12:00:00", 1, "カリン", 0.0, 5, -363.0, 190801, 1000005, 1, "2030/01/01 14:59:59", 64, 2, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1.68, "2025/01/31 12:00:00", 2, "カリン", 0.0, 6, -363.0, 190801, 1000006, 1, "2030/01/01 14:59:59", 64, 1, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.33, "2025/01/31 12:00:00", 1, "カリン", 0.0, 7, -363.0, 190801, 1000007, 1, "2030/01/01 14:59:59", 64, 2, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.18, "2025/01/31 12:00:00", 7, "ラビリスタ", -6.0, 101, -285.0, 133701, 1020101, 10201, "2030/01/01 14:59:59", 61, 3, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.77, "2025/01/31 12:00:00", 2, "クリスティーナ", -2.0, 201, -285.0, 133901, 1020102, 10201, "2030/01/01 14:59:59", 61, 1, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (15.5, "2025/01/31 12:00:00", 1, "ネネカ", 0.0, 301, -285.0, 133801, 1020103, 10201, "2030/01/01 14:59:59", 61, 6, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9.061, "2025/02/28 12:00:00", 5, "ランファ", 0.0, 101, -285.0, 134301, 1020201, 10202, "2030/01/01 14:59:59", 61, 2, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.699, "2025/02/28 12:00:00", 2, "チカ", 0.0, 201, -285.0, 134401, 1020202, 10202, "2030/01/01 14:59:59", 61, 1, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.595, "2025/03/31 12:00:00", 2, "アオイ", 0.0, 101, -285.0, 134601, 1020301, 10203, "2030/01/01 14:59:59", 61, 1, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.758, "2025/03/31 12:00:00", 2, "クローチェ", 0.0, 201, -285.0, 134501, 1020302, 10203, "2030/01/01 14:59:59", 61, 1, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.0, "2025/04/30 12:00:00", 6, "ルイズマリー", 0.0, 101, -285.0, 132302, 1020401, 10204, "2030/01/01 14:59:59", 61, 2, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.904, "2025/04/30 12:00:00", 2, "イロハ", 0.0, 201, -285.0, 132402, 1020402, 10204, "2030/01/01 14:59:59", 61, 1, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.487, "2025/04/30 12:00:00", 2, "ソノ", 0.0, 301, -285.0, 132502, 1020403, 10204, "2030/01/01 14:59:59", 61, 4, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.763, "2025/05/31 12:00:00", 2, "カノン", 0.0, 101, -285.0, 134901, 1020502, 10205, "2030/01/01 14:59:59", 61, 1, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.417, "2025/05/31 12:00:00", 3, "ツムギ", 0.0, 201, -285.0, 134801, 1020503, 10205, "2030/01/01 14:59:59", 61, 1, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.335, "2025/06/30 12:00:00", 7, "エリス", 0.0, 101, -285.0, 135001, 1020601, 10206, "2030/01/01 14:59:59", 61, 3, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.281, "2025/06/30 12:00:00", 4, "シェフィ", 0.0, 201, -285.0, 135101, 1020602, 10206, "2030/01/01 14:59:59", 61, 2, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (12.244, "2025/06/30 12:00:00", 2, "プレシア", 0.0, 301, -285.0, 135201, 1020603, 10206, "2030/01/01 14:59:59", 61, 1, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.339, "2025/07/31 12:00:00", 8, "クリア", 0.0, 101, -285.0, 135301, 1020701, 10207, "2030/01/01 14:59:59", 61, 2, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.184, "2025/07/31 12:00:00", 9, "アネモネ", 0.0, 201, -285.0, 135401, 1020702, 10207, "2030/01/01 14:59:59", 61, 7, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.906, "2025/08/31 12:00:00", 2, "アイラ", 0.0, 101, -285.0, 129101, 1020801, 10208, "2030/01/01 14:59:59", 61, 9, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (14.465, "2025/08/31 12:00:00", 2, "シナツ", 0.0, 201, -285.0, 129201, 1020802, 10208, "2030/01/01 14:59:59", 61, 1, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.662, "2025/08/31 12:00:00", 3, "ヒヨリ", 0.0, 301, -285.0, 100101, 1020803, 10208, "2030/01/01 14:59:59", 61, 4, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.915, "2025/08/31 12:00:00", 3, "レイ", 0.0, 401, -285.0, 100301, 1020804, 10208, "2030/01/01 14:59:59", 61, 1, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.042, "2025/09/30 12:00:00", 7, "ユキノ", 0.0, 101, -285.0, 135802, 1020901, 10209, "2030/01/01 14:59:59", 61, 1, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9.402, "2025/09/30 12:00:00", 1, "サツキ", 0.0, 201, -285.0, 135903, 1020902, 10209, "2030/01/01 14:59:59", 61, 4, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.16, "2025/09/30 12:00:00", 1, "ルルィ", 0.0, 301, -285.0, 136902, 1020903, 10209, "2030/01/01 14:59:59", 61, 8, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.0, "2025/10/31 12:00:00", 2, "カスミ", 0.0, 101, -285.0, 137401, 1021001, 10210, "2030/01/01 14:59:59", 61, 3, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.12, "2025/10/31 12:00:00", 1, "アラクネ", 0.0, 201, -285.0, 136001, 1021002, 10210, "2030/01/01 14:59:59", 61, 4, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.386, "2025/10/31 12:00:00", 2, "ナーナ", 0.0, 301, -285.0, 136202, 1021003, 10210, "2030/01/01 14:59:59", 61, 4, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.438, "2025/11/30 12:00:00", 4, "ユイ", 0.0, 101, -285.0, 136402, 1021101, 10211, "2030/01/01 14:59:59", 61, 3, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.35, "2025/11/30 12:00:00", 5, "ミソラ", 0.0, 201, -285.0, 136302, 1021102, 10211, "2030/01/01 14:59:59", 61, 1, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.0, "2025/12/31 12:00:00", 2, "シズル", 0.0, 101, -285.0, 136501, 1021201, 10212, "2030/01/01 14:59:59", 61, 1, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.25, "2025/12/31 12:00:00", 2, "リノ", 0.0, 201, -285.0, 137902, 1021202, 10212, "2030/01/01 14:59:59", 61, 1, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.5, "2025/12/31 12:00:00", 2, "ラビリスタ", 0.0, 301, -285.0, 106801, 1021203, 10212, "2030/01/01 14:59:59", 61, 1, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.204, "2026/01/31 12:00:00", 2, "ライラエル", 0.0, 101, -285.0, 126501, 1021301, 10213, "2030/01/01 14:59:59", 61, 1, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.176, "2026/01/31 12:00:00", 2, "ネフィ＝ネラ", 0.0, 201, -285.0, 129701, 1021302, 10213, "2030/01/01 14:59:59", 61, 1, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.602, "2026/01/31 12:00:00", 5, "ヴァイオレット", 0.0, 301, -285.0, 133101, 1021303, 10213, "2030/01/01 14:59:59", 61, 1, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.14, "2026/02/06 12:00:00", 3, "ライラエル", 0.0, 102, -285.0, 138101, 1021304, 10213, "2030/01/01 14:59:59", 61, 1, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.152, "2026/02/06 12:00:00", 7, "ネフィ＝ネラ", 0.0, 202, -285.0, 138201, 1021305, 10213, "2030/01/01 14:59:59", 61, 1, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9.688, "2026/02/06 12:00:00", 3, "ヴァイオレット", 0.0, 302, -285.0, 138001, 1021306, 10213, "2030/01/01 14:59:59", 61, 4, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.928, "2026/02/12 12:00:00", 1, "ペコリーヌ", 0.0, 401, -285.0, 138301, 1021307, 10213, "2030/01/01 14:59:59", 61, 2, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9.19, "2026/02/28 12:00:00", 2, "ワカナ", 0.0, 101, -285.0, 138702, 1021401, 10214, "2030/01/01 14:59:59", 61, 4, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.724, "2026/02/28 12:00:00", 3, "シオリ", 0.0, 201, -285.0, 138802, 1021402, 10214, "2030/01/01 14:59:59", 61, 1, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.758, "2026/03/31 12:00:00", 1, "グレイス", 0.0, 101, -285.0, 138902, 1021501, 10215, "2030/01/01 14:59:59", 61, 4, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.375, "2026/03/31 12:00:00", 4, "キョウカ", 0.0, 201, -285.0, 139002, 1021502, 10215, "2030/01/01 14:59:59", 61, 6, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.173, "2026/03/31 12:00:00", 1, "ルルィ", 0.0, 301, -285.0, 136902, 1021503, 10215, "2030/01/01 14:59:59", 61, 6, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4.202, "2026/04/30 12:00:00", 2, "ミホ", 0.0, 101, -285.0, 139202, 1021601, 10216, "2030/01/01 14:59:59", 61, 6, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.842, "2026/04/30 12:00:00", 1, "マホ", 0.0, 201, -285.0, 139302, 1021602, 10216, "2030/01/01 14:59:59", 61, 6, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4.598, "2026/04/30 12:00:00", 1, "エリカ", 0.0, 301, -285.0, 139402, 1021603, 10216, "2030/01/01 14:59:59", 61, 4, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.533, "2026/05/31 12:00:00", 3, "リリ", 0.0, 101, -285.0, 125802, 1021701, 10217, "2030/01/01 14:59:59", 61, 4, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.0, "2026/05/31 12:00:00", 3, "プレシア", 0.0, 301, -285.0, 126102, 1021702, 10217, "2030/01/01 14:59:59", 61, 3, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.214, "2026/05/31 12:00:00", 4, "クリア", 0.0, 201, -285.0, 126002, 1021703, 10217, "2030/01/01 14:59:59", 61, 3, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.781, "2026/05/31 12:00:00", 3, "リリ", 0.0, 102, -285.0, 139501, 1021704, 10217, "2030/01/01 14:59:59", 61, 1, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.529, "2026/05/31 12:00:00", 1, "クリア", 0.0, 202, -285.0, 139601, 1021705, 10217, "2030/01/01 14:59:59", 61, 2, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.195, "2026/05/31 12:00:00", 2, "プレシア", 0.0, 302, -285.0, 139701, 1021706, 10217, "2030/01/01 14:59:59", 61, 3, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (12.43, "2026/06/30 12:00:00", 3, "ルイズマリー", 0.0, 101, -285.0, 139902, 1021801, 10218, "2030/01/01 14:59:59", 61, 2, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.35, "2026/06/30 12:00:00", 3, "クレジッタ", 0.0, 201, -285.0, 140001, 1021802, 10218, "2030/01/01 14:59:59", 61, 2, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.23, "2026/07/31 12:00:00", 5, "フブキ", 0.0, 101, -285.0, 140102, 1021901, 10219, "2030/01/01 14:59:59", 61, 1, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.584, "2026/07/31 12:00:00", 2, "ヴァンピィ", 0.0, 201, -285.0, 140201, 1021902, 10219, "2030/01/01 14:59:59", 61, 1, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.8, "2026/08/31 12:00:00", 3, "クローチェ", 0.0, 201, -285.0, 126401, 1022001, 10220, "2030/01/01 14:59:59", 61, 6, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.9, "2026/08/31 12:00:00", 3, "ヴルム", 0.0, 101, -285.0, 127802, 1022002, 10220, "2030/01/01 14:59:59", 61, 4, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4.49, "2026/08/31 12:00:00", 1, "クローチェ", 0.0, 202, -285.0, 140602, 1022003, 10220, "2030/01/01 14:59:59", 61, 2, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9.42, "2026/08/31 12:00:00", 3, "ヴルム", 0.0, 102, -285.0, 140501, 1022004, 10220, "2030/01/01 14:59:59", 61, 1, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.0, "2026/08/31 12:00:00", 1, "リーザ", 0.0, 301, -285.0, 140402, 1022005, 10220, "2030/01/01 14:59:59", 61, 4, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.414, "2026/04/10 12:00:00", 2, "カリン", 0.0, 1, -416.5, 190805, 2000001, 2, "2030/01/01 14:59:59", 62, 1, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.099, "2026/04/10 12:00:00", 2, "カリン", 0.0, 2, -416.5, 190805, 2000002, 2, "2030/01/01 14:59:59", 62, 1, "ミッションをクリアして、\n報酬をゲットしましょう！");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.801, "2026/04/10 12:00:00", 2, "カリン", 0.0, 3, -416.5, 190805, 2000003, 2, "2030/01/01 14:59:59", 63, 1, "受け取ることができる\n報酬があるようです\n確認してみてください");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, "2026/04/10 12:00:00", 2, "カリン", 0.0, 4, -416.5, 190805, 2000004, 2, "2030/01/01 14:59:59", 63, 2, "報酬がもらえますよ！\nチェックしてみてください");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.12, "2026/04/10 12:00:00", 1, "カリン", 0.0, 5, -363.0, 190805, 2000005, 2, "2030/01/01 14:59:59", 64, 2, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1.68, "2026/04/10 12:00:00", 2, "カリン", 0.0, 6, -363.0, 190805, 2000006, 2, "2030/01/01 14:59:59", 64, 1, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.33, "2026/04/10 12:00:00", 1, "カリン", 0.0, 7, -363.0, 190805, 2000007, 2, "2030/01/01 14:59:59", 64, 2, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね");
